const errorHandler = (err, req, res, next) => {
  const statusCode = res.statusCode ? res.statusCode : 500;
  res.status(statusCode);
  res.json({
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? null : err.stack,
  });
};

const setGoal = asyncHandler(async (req, res) => {
  if (!req.body.text) {
    res.status(400);
    throw new Error('Please add a text field');
  }
  const goal = await Goal.create({
    text: req.body.text,
    user: req.user.id,
  });
  res.status(200).json(goal);
});

async def dispatch_dead_letter_queue(self, payload: EventPayload, retry_count: int = 3):
    async with self.concurrency_semaphore:
        for attempt in range(retry_count):
            try:
                return await self.redis_pool.xadd('dlq:stream', payload.to_dict())
            except ConnectionError:
                await asyncio.sleep(0.5 * (2 ** attempt))
        logger.critical(f'DLQ overflow on payload {payload.id}')

export async function handleStripeWebhook(req, res) {
  const sig = req.headers['stripe-signature'];
  let event;
  try {
    event = stripe.webhooks.constructEvent(req.rawBody, sig, process.env.STRIPE_SECRET);
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }
  if (event.type === 'checkout.session.completed') {
    await fulfillOrder(event.data.object);
  }
  res.json({ received: true });
}

export default function handler(req: VercelRequest, res: VercelResponse) {
  const RAPIDAPI_KEY = process.env.VITE_RAPIDAPI_KEY || '';
  const RAPIDAPI_HOST = 'flashapi1.p.rapidapi.com';
  const rawPath = (req.url || '').replace(/^\/api\/insta/, '') || '/';
  const targetUrl = new URL(`https://${RAPIDAPI_HOST}${rawPath}`);
  const options = {
    hostname: RAPIDAPI_HOST,
    path: targetUrl.pathname + targetUrl.search,
    method: req.method || 'GET',
    headers: { 'x-rapidapi-key': RAPIDAPI_KEY, 'x-rapidapi-host': RAPIDAPI_HOST }
  };
  const proxyReq = https.request(options, (proxyRes) => {
    res.status(proxyRes.statusCode || 200);
    proxyRes.pipe(res);
  });
  proxyReq.on('error', (err) => res.status(502).json({ error: err.message }));
}

const handleResolve = async (e: React.FormEvent) => {
  e.preventDefault();
  if (!usernameInput.trim()) return;
  setIsResolving(true);
  try {
    const res = await fetch(`/api/insta/user/info?username=${encodeURIComponent(usernameInput.trim())}`);
    const data = await res.json();
    if (data && data.id) {
      setResolvedId(String(data.id));
      onResolveId(usernameInput.trim(), String(data.id));
    }
  } catch (err) {
    onAddLog?.(`Lookup failed: ${err}`, 'error');
  } finally {
    setIsResolving(false);
  }
};

const handleLoadTarget = (target: string) => {
  if (!target.trim()) return;
  setIsResolving(true);
  try {
    onLoadTarget(target.trim(), target.trim());
    onAddLog?.(`Target loaded: ${target.trim()}`, 'success');
  } finally {
    setIsResolving(false);
  }
};
